import{_ as l,c as i,a as e,o as h}from"./app-DJTc4o2b.js";const n={};function s(r,a){return h(),i("div",null,a[0]||(a[0]=[e('<h1 id="狗狗的喂养与营养" tabindex="-1"><a class="header-anchor" href="#狗狗的喂养与营养"><span>狗狗的喂养与营养</span></a></h1><h2 id="基础营养需求" tabindex="-1"><a class="header-anchor" href="#基础营养需求"><span>基础营养需求</span></a></h2><h3 id="六大营养素" tabindex="-1"><a class="header-anchor" href="#六大营养素"><span>六大营养素</span></a></h3><ul><li>蛋白质：肌肉生长和修复的基础</li><li>碳水化合物：能量来源</li><li>脂肪：提供必需脂肪酸</li><li>维生素：维持正常代谢</li><li>矿物质：骨骼发展和体液平衡</li><li>水分：维持生命活动的基础</li></ul><h3 id="不同阶段的营养需求" tabindex="-1"><a class="header-anchor" href="#不同阶段的营养需求"><span>不同阶段的营养需求</span></a></h3><ul><li>幼犬期（0-1岁）：高蛋白、高能量</li><li>成犬期（1-7岁）：均衡营养</li><li>老年期（7岁以上）：低脂高纤维</li></ul><h2 id="喂食指南" tabindex="-1"><a class="header-anchor" href="#喂食指南"><span>喂食指南</span></a></h2><h3 id="喂食时间" tabindex="-1"><a class="header-anchor" href="#喂食时间"><span>喂食时间</span></a></h3><ul><li>幼犬：每天3-4次</li><li>成犬：每天2次</li><li>定时定量，保持规律</li></ul><h3 id="食量参考" tabindex="-1"><a class="header-anchor" href="#食量参考"><span>食量参考</span></a></h3><ul><li>小型犬：体重的3-5%</li><li>中型犬：体重的2.5-3.5%</li><li>大型犬：体重的2-3%</li></ul><h3 id="喂食注意事项" tabindex="-1"><a class="header-anchor" href="#喂食注意事项"><span>喂食注意事项</span></a></h3><ul><li>避免人类食物调味料</li><li>不要喂食生肉</li><li>保持食物新鲜</li><li>定期清洗食具</li><li>避免运动后立即喂食</li></ul><h2 id="狗粮选择" tabindex="-1"><a class="header-anchor" href="#狗粮选择"><span>狗粮选择</span></a></h2><h3 id="狗粮类型" tabindex="-1"><a class="header-anchor" href="#狗粮类型"><span>狗粮类型</span></a></h3><ul><li>干粮：方便储存，牙齿清洁</li><li>湿粮：适口性好，水分充足</li><li>冻干：营养保留好，价格较高</li></ul><h3 id="选购要点" tabindex="-1"><a class="header-anchor" href="#选购要点"><span>选购要点</span></a></h3><ul><li>查看配料表</li><li>注意保质期</li><li>选择适合年龄段</li><li>关注品牌口碑</li><li>适应犬种大小</li></ul><h3 id="转换狗粮注意事项" tabindex="-1"><a class="header-anchor" href="#转换狗粮注意事项"><span>转换狗粮注意事项</span></a></h3><ul><li>循序渐进，7-10天过渡</li><li>观察狗狗接受程度</li><li>注意粪便状况</li></ul><h2 id="零食选择" tabindex="-1"><a class="header-anchor" href="#零食选择"><span>零食选择</span></a></h2><h3 id="适合的零食" tabindex="-1"><a class="header-anchor" href="#适合的零食"><span>适合的零食</span></a></h3><ul><li>专业狗零食</li><li>新鲜水果（适量）</li><li>蔬菜</li><li>鸡胸肉干</li><li>鱼干</li></ul><h3 id="禁止食用" tabindex="-1"><a class="header-anchor" href="#禁止食用"><span>禁止食用</span></a></h3><ul><li>巧克力</li><li>葡萄/葡萄干</li><li>洋葱/大蒜</li><li>咖啡因</li><li>含糖食品</li><li>坚果类</li></ul><h2 id="特殊情况喂养" tabindex="-1"><a class="header-anchor" href="#特殊情况喂养"><span>特殊情况喂养</span></a></h2><h3 id="怀孕母犬" tabindex="-1"><a class="header-anchor" href="#怀孕母犬"><span>怀孕母犬</span></a></h3><ul><li>增加营养摄入</li><li>多次少量</li><li>补充钙质</li></ul><h3 id="生病期间" tabindex="-1"><a class="header-anchor" href="#生病期间"><span>生病期间</span></a></h3><ul><li>遵医嘱调整</li><li>清淡易消化</li><li>适当加水</li></ul>',30)]))}const c=l(n,[["render",s]]),t=JSON.parse('{"path":"/feeding/","title":"狗狗的喂养与营养","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1752863210000,"contributors":[{"name":"FengChen-406","username":"FengChen-406","email":"2951961339@qq.com","commits":1,"url":"https://github.com/FengChen-406"}],"changelog":[{"hash":"328872a25e7a62b301967673446dd431510c2d30","time":1752863210000,"email":"2951961339@qq.com","author":"FengChen-406","message":"初始化项目：添加VuePress文档"}]},"filePathRelative":"feeding/README.md"}');export{c as comp,t as data};
